from datetime import datetime

from urllib.parse import urlsplit


def esc(v):
    if v is None:
        return ""
    return (str(v).replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;").replace('"', "&quot;"))


def money(minor, minor_units, currency):
    if minor_units == 0:
        return "{} {}".format(minor, currency)
    sign = "-" if minor < 0 else ""
    minor = abs(int(minor))
    text = str(minor).rjust(minor_units + 1, "0")
    return "{}{}.{} {}".format(sign, text[:-minor_units], text[-minor_units:],
                               currency)


def fmt_ts(iso):
    try:
        dt = datetime.fromisoformat(iso)
        return dt.strftime("%b %-d, %-H:%M")
    except (ValueError, TypeError):
        return iso


def rel_time(iso):
    try:
        dt = datetime.fromisoformat(iso)
        now = datetime.now(dt.tzinfo)
        secs = int((now - dt).total_seconds())
    except (ValueError, TypeError):
        return ""
    if secs < 5:
        return "just now"
    if secs < 60:
        return "{}s ago".format(secs)
    if secs < 3600:
        return "{}m ago".format(secs // 60)
    if secs < 86400:
        return "{}h ago".format(secs // 3600)
    return "{}d ago".format(secs // 86400)


